/*
 * A048409  Numbers whose consecutive digits differ by 7.
 * https://oeis.org/A048409
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, base
 * Formula:   not stated
 * Range:     u8 n <= 15, u16 n <= 26, u32 n <= 41, u64 n <= 41, u128 n <= 41,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* OEIS A048409: Numbers whose consecutive digits differ by 7.
 *
 * This code constructs the nth term directly.  For n < 10 the term
 * is the digit itself.  For n >= 10 the terms are generated by
 * forming numbers of length L = ( (n-10)/5 ) + 2 composed of
 * alternating digits from the pairs (1,8), (2,9) and (7,0).
 * The ordering within each length is:
 *   1‑8  start 1
 *   2‑9  start 2
 *   7‑0  start 7
 *   1‑8  start 8
 *   2‑9  start 9
 *
 * The function works for any seq_t/idx_t implementation that
 * supports standard arithmetic and the integer types.
 */

seq_t a(idx_t n)
{
    /* Single‑digit numbers (0‑9) are the first ten terms. */
    if (n < 10)
        return (seq_t)n;

    /* Position among the multi‑digit terms. */
    idx_t t = n - 10;                 /* offset after 0..9          */
    idx_t len = t / 5 + 2;            /* length of the number (>=2) */
    idx_t offset = t % 5;             /* which of the 5 patterns   */

    /* Patterns for odd (first) and even (second) positions. */
    static const int first[5]  = {1, 2, 7, 8, 9};
    static const int second[5] = {8, 9, 0, 1, 2};

    seq_t value = (seq_t)first[offset];
    for (idx_t pos = 2; pos <= len; ++pos)
    {
        value = value * (seq_t)10 +
                (seq_t)(((pos & 1) == 0) ? second[offset] : first[offset]);
    }
    return value;
}
